#!/usr/bin/env python3
"""Inno Setup wizard bitmaps are generated by build/logo/make-icons.mjs from the Parallel Flow SVG master
and the Midnight Neon wordmark colors in theme.js (0.7.0 t1933). This wrapper just runs that script."""
import os, sys, subprocess
root = os.path.normpath(os.path.join(os.path.dirname(__file__), '..'))
script = os.path.join(root, 'build', 'logo', 'make-icons.mjs')
print('wizard BMPs are written by build/logo/make-icons.mjs (Parallel Flow, theme colors). Running that now...')
sys.exit(subprocess.call(['node', script, *sys.argv[1:]], cwd=root))
